// Guarda a última leitura do CLP e o instante de recepção (usado no watchdog)
if (msg.payload && typeof msg.payload === "object") {
    flow.set("raw", msg.payload);
    flow.set("ts", Date.now());
}
return null;

// ===== CONFIGURAÇÃO =====
const N = 10;               // quantidade de sensores
const OFFLINE_MS = 5000;    // sem leitura nova por este tempo => "sem comunicação"
const FATOR = 1;            // dividir a leitura (ex.: 10 se o DB trouxer INT em décimos de °C)
const LIM_BAIXO = null;     // ex.: 2   (null desativa)
const LIM_ALTO  = null;     // ex.: 80  (null desativa)
// ========================

function lerNomes() {
    try { return global.get("nomes", "file") || {}; }
    catch (e) { return global.get("nomes") || {}; }
}

const raw = flow.get("raw") || {};
const ts = flow.get("ts") || 0;
const nomes = lerNomes();
const online = (Date.now() - ts) < OFFLINE_MS;

const sensores = [];
for (let i = 1; i <= N; i++) {
    const tag = "T" + String(i).padStart(2, "0");
    let v = raw[tag];
    let estado = "ok";

    if (typeof v !== "number" || !isFinite(v)) {
        v = null;
        estado = online ? "falha" : "offline";
    } else {
        v = Math.round((v / FATOR) * 10) / 10;
        if (!online) estado = "offline";
        else if (LIM_ALTO !== null && v > LIM_ALTO) estado = "alto";
        else if (LIM_BAIXO !== null && v < LIM_BAIXO) estado = "baixo";
    }
    sensores.push({ idx: i, tag: tag, nome: nomes[i] || ("Temperatura " + i), valor: v, estado: estado });
}

msg.payload = { online: online, sensores: sensores };
return msg;

// Recebe {rename:{idx,name}} do painel e persiste o nome
const r = msg.payload && msg.payload.rename;
if (!r) return null;

const i = parseInt(r.idx, 10);
if (!(i >= 1 && i <= 10)) return null;

const nome = String(r.name === undefined || r.name === null ? "" : r.name).trim().slice(0, 40);

let nomes;
let store = "file";
try { nomes = global.get("nomes", store) || {}; }
catch (e) { store = undefined; nomes = global.get("nomes") || {}; }

if (nome) nomes[i] = nome; else delete nomes[i];

if (store) global.set("nomes", nomes, store);
else global.set("nomes", nomes);

return msg;

// Liga aqui a MESMA saída que alimenta o "Painel temperaturas".
// Só guarda a última leitura; quem envia ao Sheets é o relógio de 1 min.
const p = msg.payload;
if (p && Array.isArray(p.sensores)) {
    global.set('sheets_ultima_leitura', {
        ts: Date.now(),
        online: !!p.online,
        sensores: p.sensores
    });
    node.status({ fill: 'green', shape: 'dot', text: p.sensores.length + ' sensores · ' + new Date().toLocaleTimeString('pt-BR') });
}
return null;

// ===== CONFIGURE AQUI =====================================================
const URL_SHEETS = 'https://script.google.com/macros/s/AKfycbxYocrAWlPE2jO2kO5_Z4Lw0AHmK058L4qQ2FvrWIbWywse5d5px4uB2-Yn-6JfM21jyQ/exec';
const TOKEN       = 'BTRIOSUL';   // igual ao TOKEN do Apps Script
const IDADE_MAX_S = 150;     // leitura mais velha que isso é gravada como "sem dados"
const MAX_FILA    = 1440;    // linhas guardadas se o Sheets ficar fora do ar (1440 = 24 h)
// ===========================================================================

const L = global.get('sheets_ultima_leitura');
if (!L) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'sem leitura ainda' });
    return null;
}

const fresca = (Date.now() - L.ts) / 1000 <= IDADE_MAX_S;
const valores = {};
const sensores = [];
for (const s of L.sensores) {
    const tag = String(s.tag != null && s.tag !== '' ? s.tag : 'S' + s.idx).trim();
    sensores.push({ tag: tag, nome: s.nome, idx: s.idx });
    const v = s.valor;
    valores[tag] = (fresca && typeof v === 'number' && isFinite(v)) ? Math.round(v * 100) / 100 : null;
}

const fila = global.get('sheets_fila') || [];
fila.push({ ts: Date.now(), online: fresca && L.online, valores: valores, sensores: sensores });
while (fila.length > MAX_FILA) fila.shift();
global.set('sheets_fila', fila);

msg.enviados = fila.length;                 // quantas linhas vão neste POST
msg.url = URL_SHEETS;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.requestTimeout = 30000;
msg.payload = { token: TOKEN, linhas: fila.slice() };
return msg;

// Só remove da fila o que o Sheets confirmou ter recebido.
let r = msg.payload;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }
const ok = msg.statusCode === 200 && r && typeof r === 'object' && r.ok === true;
const hora = new Date().toLocaleTimeString('pt-BR');

if (ok) {
    const fila = global.get('sheets_fila') || [];
    fila.splice(0, msg.enviados || 0);
    global.set('sheets_fila', fila);
    node.status({ fill: 'green', shape: 'dot', text: 'gravadas ' + r.gravadas + ' · ' + hora });
} else {
    const fila = global.get('sheets_fila') || [];
    const motivo = (r && r.erro) ? r.erro : ('HTTP ' + msg.statusCode);
    node.status({ fill: 'red', shape: 'ring', text: motivo + ' · fila ' + fila.length });
    node.warn('Sheets: envio falhou (' + motivo + '). Linhas mantidas na fila: ' + fila.length);
}
return null;
